/* engines/howler.js — part of the universal player. Generated by the one-off split;
 * every top-level name lives on the shared context P (see context.js). */
import { P } from "../context.js";

export function install(P) {


  /*
   * Howler.js normally manages its own hidden <audio> element. We hand it
   * the player's shared element instead, so playback, seeking, time and
   * Media Session keep working exactly as in the other engines while Howler
   * remains the component issuing play/pause/seek commands.
   */
  async function createHowler(url, startAt, autoplay) {
    try { await P.loadHowlerScript(); } catch {
      P.fallbackToHtml5();
      P.notify("engine");
      return false;
    }
    if (!window.Howl || !window.Howler) return false;

    P.showEngineUi("howler");
    P.audio.src = url;
    P.audio.load();

    const global = window.Howler;
    const obtain = global._obtainHtml5Audio;
    global._obtainHtml5Audio = () => P.audio;
    try {
      P.howl = new window.Howl({
        src: [url],
        html5: true,
        preload: true,
        loop: false,
        volume: P.state.volume,
        muted: P.state.muted,
      });
    } catch {
      P.howl = null;
    } finally {
      global._obtainHtml5Audio = obtain;
    }
    if (!P.howl) {
      P.fallbackToHtml5();
      P.notify("engine");
      return false;
    }

    P.howl.on("loaderror", () => {
      P.fallbackToHtml5();
      P.notify("engine");
    });
    P.howl.once("load", () => {
      P.finishLoading();
      if (startAt) P.setTime(startAt);
      if (autoplay) P.attemptPlay();
    });
    return true;
  }
  Object.assign(P, { createHowler });
}
